/**
 * Creates HeartbeatEndpointTask with the given conf, context and
 * StorageContainerManager client side proxy.
 *
 * @param conf Configuration
 * @param context StateContext
 * @param proxy StorageContainerDatanodeProtocolClientSideTranslatorPB
 *
 * @return HeartbeatEndpointTask
 */
private HeartbeatEndpointTask getHeartbeatEndpointTask(Configuration conf, StateContext context, StorageContainerDatanodeProtocolClientSideTranslatorPB proxy) {
    DatanodeDetails datanodeDetails = DatanodeDetails.newBuilder().setUuid(UUID.randomUUID().toString()).setHostName("localhost").setIpAddress("127.0.0.1").build();
    EndpointStateMachine endpointStateMachine = Mockito.mock(EndpointStateMachine.class);
    Mockito.when(endpointStateMachine.getEndPoint()).thenReturn(proxy);
    return HeartbeatEndpointTask.newBuilder().setConfig(conf).setDatanodeDetails(datanodeDetails).setContext(context).setEndpointStateMachine(endpointStateMachine).build();
}

