    assertTrue("Available volume should be positive", volume.getAvailable() > 0);
    // Shutdown the volume.
    volume.shutdown();
    // Volume state should be "NON_EXISTENT" when volume is shutdown.
    assertEquals(volume.getStorageState(), HddsVolume.VolumeState.NON_EXISTENT);
