@Test
public void test() throws IOException {
    //given
    OzoneConfiguration conf = new OzoneConfiguration();
    Node2ContainerMap node2ContainerMap = new Node2ContainerMap();
    Mapping mapping = Mockito.mock(Mapping.class);
    when(mapping.getContainer(anyLong())).thenAnswer((Answer<ContainerInfo>) invocation -> new Builder().setReplicationFactor(ReplicationFactor.THREE).setContainerID((Long) invocation.getArguments()[0]).build());
    ContainerStateManager containerStateManager = new ContainerStateManager(conf, mapping);
    when(mapping.getStateManager()).thenReturn(containerStateManager);
    ReplicationActivityStatus replicationActivityStatus = new ReplicationActivityStatus();
    ContainerReportHandler reportHandler = new ContainerReportHandler(mapping, node2ContainerMap, replicationActivityStatus);
    DatanodeDetails dn1 = TestUtils.randomDatanodeDetails();
    DatanodeDetails dn2 = TestUtils.randomDatanodeDetails();
    DatanodeDetails dn3 = TestUtils.randomDatanodeDetails();
    DatanodeDetails dn4 = TestUtils.randomDatanodeDetails();
    node2ContainerMap.insertNewDatanode(dn1.getUuid(), new HashSet<>());
    node2ContainerMap.insertNewDatanode(dn2.getUuid(), new HashSet<>());
    node2ContainerMap.insertNewDatanode(dn3.getUuid(), new HashSet<>());
    node2ContainerMap.insertNewDatanode(dn4.getUuid(), new HashSet<>());
    PipelineSelector pipelineSelector = Mockito.mock(PipelineSelector.class);
    Pipeline pipeline = new Pipeline("leader", LifeCycleState.CLOSED, ReplicationType.STAND_ALONE, ReplicationFactor.THREE, PipelineID.randomId());
    when(pipelineSelector.getReplicationPipeline(ReplicationType.STAND_ALONE, ReplicationFactor.THREE)).thenReturn(pipeline);
    long c1 = containerStateManager.allocateContainer(pipelineSelector, ReplicationType.STAND_ALONE, ReplicationFactor.THREE, "root").getContainerInfo().getContainerID();
    long c2 = containerStateManager.allocateContainer(pipelineSelector, ReplicationType.STAND_ALONE, ReplicationFactor.THREE, "root").getContainerInfo().getContainerID();
    //when
    //initial reports before replication is enabled. 2 containers w 3 replicas.
    reportHandler.onMessage(new ContainerReportFromDatanode(dn1, createContainerReport(new long[] { c1, c2 })), this);
    reportHandler.onMessage(new ContainerReportFromDatanode(dn2, createContainerReport(new long[] { c1, c2 })), this);
    reportHandler.onMessage(new ContainerReportFromDatanode(dn3, createContainerReport(new long[] { c1, c2 })), this);
    reportHandler.onMessage(new ContainerReportFromDatanode(dn4, createContainerReport(new long[] {})), this);
    Assert.assertEquals(0, publishedEvents.size());
    replicationActivityStatus.enableReplication();
    //no problem here
    reportHandler.onMessage(new ContainerReportFromDatanode(dn1, createContainerReport(new long[] { c1, c2 })), this);
    Assert.assertEquals(0, publishedEvents.size());
    //container is missing from d2
    reportHandler.onMessage(new ContainerReportFromDatanode(dn2, createContainerReport(new long[] { c1 })), this);
    Assert.assertEquals(1, publishedEvents.size());
    ReplicationRequest replicationRequest = (ReplicationRequest) publishedEvents.get(0);
    Assert.assertEquals(c2, replicationRequest.getContainerId());
    Assert.assertEquals(3, replicationRequest.getExpecReplicationCount());
    Assert.assertEquals(2, replicationRequest.getReplicationCount());
    //container was replicated to dn4
    reportHandler.onMessage(new ContainerReportFromDatanode(dn4, createContainerReport(new long[] { c2 })), this);
    //no more event, everything is perfect
    Assert.assertEquals(1, publishedEvents.size());
    //c2 was found at dn2 (it was missing before, magic)
    reportHandler.onMessage(new ContainerReportFromDatanode(dn2, createContainerReport(new long[] { c1, c2 })), this);
    //c2 is over replicated (dn1,dn2,dn3,dn4)
    Assert.assertEquals(2, publishedEvents.size());
    replicationRequest = (ReplicationRequest) publishedEvents.get(1);
    Assert.assertEquals(c2, replicationRequest.getContainerId());
    Assert.assertEquals(3, replicationRequest.getExpecReplicationCount());
    Assert.assertEquals(4, replicationRequest.getReplicationCount());
}

